/**
 * Column dictionary: what every source column means.
 *  - ODK form fields: label / hint / type / choices taken from the XLSForms
 *    (generated by scripts/build_odk_dictionary.py → odk_dictionary.json).
 *  - ODK Central submission metadata and entity-list system columns: documented here.
 *  - Bird files and entity-list attributes: documented here; statements checked against the data
 *    where possible, and marked "not documented" where the meaning is not in the provided files.
 */
import odk from './odk_dictionary.json'

interface OdkField {
  type: string
  label?: string
  hint?: string
  calc?: string
  choices?: [string, string][]
  choices_from?: string
}
const ODK = odk as unknown as Record<string, Record<string, OdkField>>

