const GEO_PART: Record<string, string> = { Latitude: 'latitude (decimal degrees)', Longitude: 'longitude (decimal degrees)', Altitude: 'altitude (m)', Accuracy: 'GPS accuracy (m, smaller is better)' }

function describeOdk(f: OdkField, part?: string): string {
  const lines: string[] = []
  if (f.label) lines.push(`Form question: “${f.label}”`)
  if (f.hint) lines.push(`Hint: ${f.hint}`)
  if (part) lines.push(`This column holds the ${GEO_PART[part]} of that GPS point.`)
  if (!f.label && f.calc) lines.push(`Calculated by the form: ${f.calc.length > 180 ? `${f.calc.slice(0, 180)}…` : f.calc}`)
  lines.push(`ODK type: ${f.type}`)
  if (f.choices?.length) lines.push(`Choices: ${f.choices.slice(0, 12).map(([n, l]) => (n === l ? n : `${n} = ${l}`)).join(' · ')}${f.choices.length > 12 ? ' …' : ''}`)
  if (f.choices_from) lines.push(`Choices come from the entity list ${f.choices_from}.`)
  return lines.join('\n')
}

export function describeColumn(datasetId: string, name: string): string | undefined {
  const specific = SPECIFIC[datasetId]?.[name]
  if (specific) return specific
  if (SUBMISSION_META[name]) return SUBMISSION_META[name]
  const table = ODK[datasetId]
  if (table) {
    if (table[name]) return describeOdk(table[name])
    const m = /^(.*)-(Latitude|Longitude|Altitude|Accuracy)$/.exec(name)
    if (m && table[m[1]]) return describeOdk(table[m[1]], m[2])
  }
  if (ENTITY_SYSTEM[name]) return ENTITY_SYSTEM[name]
  return undefined
}
